CREATE TABLE invoices (id VARCHAR2(36) PRIMARY KEY, operation_id VARCHAR2(120) NOT NULL UNIQUE, customer_id VARCHAR2(120) NOT NULL, subtotal NUMBER(14,2) NOT NULL, tax NUMBER(14,2) NOT NULL, total NUMBER(14,2) NOT NULL, status VARCHAR2(30) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE invoice_lines (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoice_id VARCHAR2(36) NOT NULL REFERENCES invoices(id), description VARCHAR2(300) NOT NULL, quantity NUMBER(10) NOT NULL CHECK(quantity > 0), unit_price NUMBER(14,2) NOT NULL);